   <div class="view-tools"><button id="stress" title="Show stress in physical connections">${L("activity")} Stress</button><span class="tool-divider"></span><button class="icon-button" data-view="perspective" title="Perspective view">${L("box")}</button><button class="icon-button" data-view="top" title="Top view">${L("scan")}</button><button class="icon-button" data-view="front" title="Front view">${L("panel-top")}</button><button class="icon-button" data-view="side" title="Side view">${L("panel-left")}</button><button id="grid" class="icon-button active" title="Toggle construction grid">${L("grid-2x2")}</button></div>
